import fs from 'node:fs';
import { createHash } from 'node:crypto';

// Lista cerrada; ni el proyecto ni el modelo eligen rutas del sistema de archivos.
export const REFERENCE_SECTIONS = {
  design: ['docs/interfaz/design.md', 'docs/interfaz/DESIGN.template.md'],
  ui_quick: ['docs/interfaz/rapido.md'],
  ui_schema: ['docs/interfaz/proposal.example.json', 'docs/interfaz/project.example.json', 'docs/interfaz/context.example.json'],
  ui_figma: ['docs/interfaz/figma.source.example.json', 'docs/interfaz/figma.example.json', 'docs/interfaz/calidad-visual.md'],
  backlog: ['docs/backlog/guia-rapida.md', 'docs/backlog/flujo.md', 'docs/backlog/brief.example.json',
    'docs/backlog/context.example.json', 'docs/backlog/backlog.example.json',
    'docs/backlog/proposal.example.json', 'docs/backlog/project.example.json'],
  board: ['docs/backlog/tablero.md', 'docs/backlog/concurrencia.md',
    'docs/backlog/board-context.example.json', 'docs/backlog/board-proposal.example.json',
    'docs/backlog/board-transition.example.json', 'docs/backlog/board-sprint.example.json',
    'docs/backlog/board-sprint-lifecycle.example.json', 'docs/backlog/board-create.example.json',
    'docs/backlog/board-comment.example.json', 'docs/backlog/operation.example.json'],
  jira: ['docs/backlog/jira.md', 'docs/backlog/concurrencia.md'],
  traceability: ['docs/trazabilidad.md', '.opencode/skills/laid-methodology/SKILL.md',
    '.opencode/skills/laid-agents-md/SKILL.md'],
  ui: ['docs/interfaz/flujo.md', 'docs/interfaz/proposal.example.json',
    'docs/interfaz/project.example.json', 'docs/interfaz/brief.example.json',
    'docs/interfaz/context.example.json', 'docs/interfaz/figma.example.json', 'docs/interfaz/calidad-visual.md'],
};

export function reference(section) {
  if (!Object.hasOwn(REFERENCE_SECTIONS, section)) throw new Error('Referencia LAID: sección desconocida');
  let bundle;
  try { bundle = JSON.parse(fs.readFileSync(new URL('./reference-bundle.json', import.meta.url), 'utf8')); }
  catch { throw new Error('Referencia LAID: paquete ausente o inválido; reinstala el plugin completo'); }
  const documents = REFERENCE_SECTIONS[section].map(id => {
    const item = bundle.documents?.[id];
    if (!item || typeof item.text !== 'string' || !item.text.trim()
      || createHash('sha256').update(item.text).digest('hex') !== item.sha256)
      throw new Error(`Referencia LAID: contrato ausente o alterado: ${id}`);
    return { id, ...item };
  });
  return { section, documents,
    note: 'Contratos del plugin, no archivos del proyecto. Los ejemplos no son datos aprobados. No añadir estos IDs a source_files; el motor conserva el paquete utilizado.' };
}

