import * as fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';
import { BACKLOG_STAGES, BACKLOG_CHECKS, validateBacklog } from './backlog.mjs';
import { validateOperation, validateReceipt } from './board.mjs';
import { validateFigmaManifest } from './figma-schema.mjs';
import { parseUniqueJSON, materializeFigma } from './prototype-tools.mjs';

export const STAGES = ['encargo', 'visual', 'estructura', 'prototipo', 'entrega'];
const CHECKS = ['contrast', 'browser', 'browser_mobile', 'browser_desktop', 'ux_a11y_review'];
const text = v => typeof v === 'string' && v.trim().length > 0;
const object = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const need = (ok, message) => { if (!ok) throw new Error(message); };
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const read = file => JSON.parse(fs.readFileSync(file, 'utf8'));
const write = (file, value) => fs.writeFileSync(file, JSON.stringify(value, null, 2) + '\n', { flag: 'wx' });
const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const pluginRoot = path.dirname(fileURLToPath(import.meta.url));

// El SDK V2 usa text en user y content[] en assistant. Solo texto visible,
// nunca reasoning ni resultados de herramientas, presenta una revisión humana.
function visibleText(message) {
  return message.type === 'assistant' && Array.isArray(message.content)
    ? message.content.filter(part => part.type === 'text' && text(part.text)).map(part => part.text).join('\n')
    : message.text;
}

export function snapshotDigest(entries) {
  const hash = createHash('sha256');
  // Conserva el orden nativo del algoritmo histórico, también en Windows.
  for (const [relative, bytes] of entries.sort((a, b) => {
    const x = a[0].split('/').join(path.sep), y = b[0].split('/').join(path.sep);
    return x < y ? -1 : x > y ? 1 : 0;
  })) {
    const name = Buffer.from(relative);
    const size = Buffer.alloc(8); size.writeBigUInt64BE(BigInt(name.length));
    hash.update(size).update(name).update(createHash('sha256').update(bytes).digest());
  }
  return hash.digest('hex');
}

export function workflow(directory, profile = 'ui') {
  need(['ui', 'backlog', 'board'].includes(profile), 'Perfil inválido');
  const board = profile === 'board';
  const backlog = profile !== 'ui';
  const stages = board ? ['operacion'] : backlog ? BACKLOG_STAGES : STAGES;
  const checks = backlog ? BACKLOG_CHECKS : CHECKS;
  const approvers = backlog ? [] : ['design', 'po'];
  const activeStages = context => !backlog && context.workflow_policy === 'rapid' ? ['prototipo', 'entrega'] : stages;
  const root = fs.realpathSync(directory);
  function safe(...parts) {
    const target = path.resolve(root, ...parts);
    const relative = path.relative(root, target);
    need(!relative.startsWith('..') && !path.isAbsolute(relative), 'Ruta fuera del proyecto');
    let current = root;
    for (const part of relative.split(path.sep).filter(Boolean)) {
      current = path.join(current, part);
      try { need(!fs.lstatSync(current).isSymbolicLink(), 'No se admiten enlaces ni junctions'); }
      catch (error) { if (error.code !== 'ENOENT') throw error; }
    }
    return target;
  }
  function taskPath(task) {
    need(typeof task === 'string' && /^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(task)
      && !/^(con|prn|aux|nul|com[0-9]|lpt[0-9])$/i.test(task), 'ID de tarea inválido');
    return safe('.laid', profile, task);
  }
  function files(folder) {
    safe(folder);
    return fs.readdirSync(folder).sort().flatMap(name => {
      const file = safe(folder, name);
      const stat = fs.statSync(file);
      need(stat.isFile() || stat.isDirectory(), 'Tipo de archivo no permitido');
      need(!/^\.env/i.test(name) && !/\.(pem|key)$/i.test(name)
        && !['secrets', 'prod-data'].includes(name.toLowerCase()), 'Archivo sensible excluido');
      return stat.isDirectory() ? files(file) : [file];
    });
  }
  function digest(folder) {
    return snapshotDigest(files(folder).map(file => [path.relative(folder, file).split(path.sep).join('/'), fs.readFileSync(file)]));
  }
  function append(folder, events, value) {
    const event = { seq: events.length + 1, at: new Date().toISOString(), ...value };
    fs.appendFileSync(safe(folder, 'events.jsonl'), JSON.stringify(event) + '\n');
    return event;
  }
  function locked(task, action) {
    // ponytail: un escritor local por tarea; usar almacén transaccional para varios hosts.
    const lock = safe(taskPath(task), '.lock');
    fs.closeSync(fs.openSync(lock, 'wx'));
    try { return action(); } finally { fs.unlinkSync(lock); }
  }
  function validateProject(context) {
    need(object(context) && !JSON.stringify(context).includes('SUSTITUIR'), 'Completa el contexto del proyecto');
    for (const key of ['agreement_ref', 'data_policy', 'owner']) need(text(context[key]), `Falta ${key}`);
    need(['manual', 'asistida', 'mixta', 'agente'].includes(context.mode), 'Modo inválido');
    if (!backlog) need(object(context.approvers), 'Faltan aprobadores');
    if (!backlog) need(context.review_policy === undefined || ['final', 'staged'].includes(context.review_policy), 'Política de revisión inválida');
    if (!backlog) {
      need(context.purpose === undefined || ['formal','exploration'].includes(context.purpose), 'purpose: formal o exploration');
      for (const [key,value] of Object.entries({ owner: context.owner, ...context.approvers }))
        need(!/^\s*(pendiente|pending|unknown)\s*$/i.test(value), `${key}: declara responsable, no un placeholder`);
      need(!/^\s*(pendiente|pending)/i.test(context.agreement_ref), 'agreement_ref: acuerdo real o referencia explícita de exploración, no aprobación pendiente');
      need(context.workflow_policy === undefined || ['rapid', 'staged'].includes(context.workflow_policy), 'workflow_policy: rapid o staged');
      need(context.workflow_policy !== 'rapid' || context.review_policy !== 'staged', 'Un acuerdo staged no admite workflow_policy rapid');
    }
    for (const role of [...approvers, ...(!backlog && context.mode === 'agente' ? ['senior'] : [])])
      need(text(context.approvers[role]), `Falta responsable ${role}`);
  }
  function createProject(config) {
    need(profile === 'ui', 'Creación de configuración solo para Interfaz');
    validateProject(config);
    fs.mkdirSync(safe('.laid'), { recursive: true });
    const file = safe('.laid', 'ui-project.json');
    config = { ...config, review_policy: config.review_policy ?? 'final',
      workflow_policy: config.workflow_policy ?? (config.review_policy === 'staged' ? 'staged' : 'rapid') };
    write(file, config); // wx: una configuración existente nunca se sobrescribe.
    return { path: '.laid/ui-project.json', config };
  }
  function validateContext(context) {
    validateProject(context);
    for (const key of ['story', 'objective']) need(text(context[key]), `Falta ${key}`);
    if(!backlog&&context.budget_minutes!==undefined)need(Number.isInteger(context.budget_minutes)&&context.budget_minutes>=5&&context.budget_minutes<=60,'budget_minutes: entero entre 5 y 60');
    need(object(context.criteria) && (backlog || Object.keys(context.criteria).length > 0)
      && Object.entries(context.criteria).every(([k, v]) => text(k) && text(v) && !checks.includes(k)), 'Criterios inválidos');
    if (board) {
      need(object(context.tracker) && text(context.tracker.adapter) && text(context.tracker.project), 'Falta tracker del proyecto');
      need(['manual', 'asistida', 'mixta', 'agente'].includes(context.execution_mode), 'Falta modo del elemento');
    }
  }
  function init(task) {
    const folder = taskPath(task);
    const input = read(safe('.laid', 'intake', ...(backlog ? [profile] : []), task, 'context-input.json'));
    const project = read(safe('.laid', `${backlog ? 'backlog' : 'ui'}-project.json`));
    need(object(input) && object(project), 'Contexto y proyecto deben ser objetos JSON');
    // El modelo puede proponer el encargo, pero no cambiar identidades ni el acuerdo.
    const projectKeys = ['agreement_ref', 'data_policy', 'owner', 'mode', ...(!backlog ? ['approvers'] : []), ...(board ? ['tracker'] : [])];
    for (const key of projectKeys) {
      need(project[key] !== undefined, `Falta ${key} en ${profile}-project.json`);
      if (input[key] !== undefined) need(JSON.stringify(input[key]) === JSON.stringify(project[key]), `Conflicto con el proyecto: ${key}`);
    }
    const context = { ...input, ...Object.fromEntries(projectKeys.map(k => [k, project[k]])),
      ...(!backlog ? { review_policy: project.review_policy ?? 'final',
        ...(project.purpose ? { purpose: project.purpose } : {}),
        ...(project.workflow_policy ? { workflow_policy: project.workflow_policy } : {}) } : {}) };
    if (!backlog) {
      need(input.requirements_source === undefined || ['independent', 'jira'].includes(input.requirements_source), 'requirements_source: independent o jira');
      need(input.design_target === undefined || ['preview', 'figma'].includes(input.design_target), 'design_target: preview o figma');
      need(context.workflow_policy !== 'rapid' || context.review_policy === 'final', 'Rapid requiere revisión final');
      if (context.workflow_policy === 'rapid') {
        const trackerFile=safe('.laid','backlog-project.json');
        need(input.requirements_source !== undefined || !fs.existsSync(trackerFile) || !read(trackerFile).tracker,
          'Elige requirements_source independent o jira para este encargo; tracker configurado no impone Jira');
        context.requirements_source ??= 'independent'; context.design_target ??= 'preview';
        need(context.requirements_source !== 'jira' || (text(input.jira_issue) && text(input.jira_source_ref)), 'Jira requiere issue y referencia de lectura real');
      }
    }
    if (!backlog && input.review_policy !== undefined)
      need(input.review_policy === context.review_policy, 'Conflicto con el proyecto: review_policy');
    validateContext(context);
    fs.mkdirSync(safe('.laid', profile), { recursive: true });
    fs.mkdirSync(folder, { recursive: true });
    return locked(task, () => {
      // Un borrador previo no es un expediente formal; nunca adoptar registros parciales.
      need(fs.readdirSync(folder).every(name => name === 'drafts' || name === '.lock'),
        'Expediente ya inicializado o con archivos formales/parciales; no se sobrescribe');
      const drafts = safe(folder, 'drafts');
      if (fs.existsSync(drafts)) {
        need(fs.readdirSync(drafts).every(stage => stages.includes(stage)), 'Etapa de borrador desconocida');
        files(drafts); // Comprueba enlaces, tipos y archivos sensibles antes de escribir contexto.
      }
      write(safe(folder, 'context.json'), context);
      for (const stage of stages) fs.mkdirSync(safe(folder, 'drafts', stage), { recursive: true });
      append(folder, [], { type: 'init', context_sha256: sha(fs.readFileSync(safe(folder, 'context.json'))) });
      return status(task);
    });
  }
  function verify(folder, event, verified) {
    need(digest(safe(folder, 'revisions', event.stage, String(event.version))) === (event.migration?.storage_sha256 ?? event.sha256), 'Snapshot alterado');
    for (const hash of [event.context_bundle, event.source_bundle, event.migration?.original_bundle].filter(Boolean)) {
      need(/^[a-f0-9]{64}$/.test(hash), 'Referencia compartida inválida');
      if (verified.has(hash)) continue;
      need(sha(fs.readFileSync(safe('.laid', 'objects', `${hash}.json`))) === hash, 'Contexto o fuentes compartidas alteradas');
      verified.add(hash);
    }
    if (event.migration) {
      need(/^[a-f0-9]{64}$/.test(event.migration.original_bundle), 'Migración sin original');
