      need(mode === 'full' || reports.some(e => views.some(v => v.file === e.file && v.state === e.state) && e.report.viewport.width === 320), 'Falta reflow esencial a 320px');
      return { mode, coverage: mode === 'full' ? 'exhaustive' : 'representative', source_sha256,
        reports: reports.map(e => ({ seq: e.seq, file: e.file, state: e.state, report: e.report })) };
    }
    if (entry) need(Array.isArray(proposal.layout_states) && proposal.layout_states.length > 0 && proposal.layout_states.length <= 50
      && new Set(proposal.layout_states).size === proposal.layout_states.length && proposal.layout_states.every(text),
      'Declara layout_states con los estados representativos (o todos en modo full) antes de congelar');
    if (entry) for (const state of proposal.layout_states)
      for (const width of mode === 'full' ? [320, 390, 768, 1440] : [390, 1440]) need(reports.some(e => e.file === entry && e.state === state && e.report.viewport.width === width),
        `Falta geometría de ${entry} · ${state} a ${width}px`);
    if (entry && mode === 'essential') need(reports.some(e => e.file === entry && proposal.layout_states.includes(e.state)
      && e.report.viewport.width === 320), 'Falta reflow esencial a 320px');
    need(!entry || reports.some(e => e.file === entry), 'Falta medición del prototipo navegable');
    for (const html of files(folder).filter(file => file.endsWith('.html') && (mode === 'full' || !entry))) {
      const name = path.relative(folder, html).replaceAll('\\', '/');
      need(reports.some(e => e.file === name), `Falta geometría de ${name}`);
    }
    if (mode === 'full') for (const item of proposal.figma_exports ?? []) need(reports.some(e => e.file === item.file
      && e.report.viewport.width === item.viewport.width && e.report.viewport.height === item.viewport.height), `Falta geometría de ${item.file}`);
    return { mode, coverage: mode === 'full' ? 'exhaustive' : 'representative', source_sha256,
      reports: reports.map(e => ({ seq: e.seq, file: e.file, state: e.state, report: e.report })) };
  }
  function layoutViews(folder, proposal) {
    need(Array.isArray(proposal.layout_views) && proposal.layout_views.length > 0 && proposal.layout_views.length <= 50, 'layout_views: lista de {file,state,selector?,query?}');
    const keys = new Set();
    for (const [i, view] of proposal.layout_views.entries()) {
      need(object(view) && text(view.state) && !/(?:mobile|desktop|max-density)-\d+/i.test(view.state), `layout_views[${i}].state: nombre semántico sin viewport, ejemplo resumen`);
      need(typeof view.file === 'string' && /^[A-Za-z0-9_-][A-Za-z0-9_./-]*\.html$/.test(view.file) && !view.file.split('/').includes('..')
        && fs.statSync(safe(folder, view.file)).isFile(), `layout_views[${i}].file: HTML relativo al borrador, ejemplo resumen.html`);
      need(view.selector === undefined || text(view.selector), `layout_views[${i}].selector: CSS de estado visible`);
      need(view.query === undefined || (typeof view.query === 'string' && !/[#\r\n()]/.test(view.query) && !/^https?:/i.test(view.query)), `layout_views[${i}].query: parámetros URL locales, no JavaScript`);
      const key = `${view.file}|${view.state}`; need(!keys.has(key), `layout_views[${i}]: vista duplicada`); keys.add(key);
    }
    return proposal.layout_views;
  }
  function layoutView(task, state) {
    const folder = safe(taskPath(task), 'drafts', 'prototipo'), proposal = read(safe(folder, 'proposal.json'));
    if (!proposal.layout_views) return undefined;
    const view = layoutViews(folder, proposal).find(v => v.state === state);
    need(view, 'Estado no declarado en layout_views'); return view;
  }
  function measurementPlan(task) {
    const data = load(task), folder = safe(data.folder,'drafts','prototipo'), proposal = read(safe(folder,'proposal.json'));
    const views = layoutViews(folder,proposal), widths = proposal.layout_mode === 'full' ? [320,390,768,1440] : [390,1440];
    const items = views.flatMap(view => widths.map(width => ({ ...view,width })));
    if (proposal.layout_mode !== 'full') items.push({ ...(views.find(v => v.state === proposal.reflow_state) ?? views[0]), width: 320 });
    const stamp = layoutStamp(task), checker = sha(fs.readFileSync(new URL('./layout-audit.mjs',import.meta.url)));
    const latest = new Map();
    for (const e of data.events.filter(e => e.type === 'layout_checked' && e.checker_sha256 === checker
      && (e.view_sha256 ? fs.existsSync(safe(folder,e.file)) && e.view_sha256 === viewDigest(folder,e.file) : e.source_sha256 === stamp)))
      latest.set(`${e.file}|${e.state}|${e.report.viewport.width}`, e);
    const valid = new Set([...latest].filter(([,e]) => e.report.passed).map(([key]) => key));
    const pending = items.filter(item => !valid.has(`${item.file}|${item.state}|${item.width}`));
    return { total: items.length, reused: items.length-pending.length, pending };
  }
  function preflight(task, stage) {
    need(profile === 'ui' && stages.includes(stage), 'Prevalidación solo de Interfaz');
    const data = load(task), folder = safe(data.folder, 'drafts', stage), errors = [];
    const check = (field, action) => { try { action(); } catch (error) { errors.push({ field, message: error.message }); } };
    let proposal;
    check('proposal.json', () => { proposal = parseUniqueJSON(fs.readFileSync(safe(folder, 'proposal.json'),'utf8')); });
    if (!proposal) return { ready: false, errors, next: 'ui_prepare crea la plantilla; no usar submit para diagnosticar' };
    check('proposal', () => validateProposal(proposal));
    check('stage', () => need(activeStages(data.context).includes(stage), 'Etapa no requerida; usa prototipo en rapid'));
    check('predecessors', () => need(activeStages(data.context).slice(0, activeStages(data.context).indexOf(stage)).every(s => ready(states(data)[s])), 'Predecesoras no vigentes'));
    if (data.context.review_policy === 'final') check('scope_change', () => need(typeof proposal.scope_change === 'boolean', 'Booleano tras comparar brief y fuente elegida; no inferir aprobación'));
    for (const [i, source] of (Array.isArray(proposal.source_files) ? proposal.source_files : []).entries())
      check(`source_files[${i}]`, () => { need(text(source) && !path.isAbsolute(source) && !source.split(/[\\/]/).some(p => p === '..' || /^\.env/i.test(p) || /\.(pem|key)$/i.test(p) || ['secrets','prod-data','opencode.jsonc'].includes(p.toLowerCase())), 'Fuente no permitida'); fs.readFileSync(safe(source)); });
    const checks = new Map((proposal.checks ?? []).map(c => [c.id, c]));
    const required = ['prototipo','entrega'].includes(stage) ? [...CHECKS, ...Object.keys(data.context.criteria), ...(data.context.review_policy === 'final' ? ['scope_review','independent_review'] : [])] : stage === 'visual' ? ['contrast'] : [];
    for (const id of required) check(`checks.${id}`, () => need(checks.get(id)?.status === 'passed', `${id}: falta comprobación real passed`));
    for (const c of checks.values()) check(`checks.${c.id}.evidence`, () => {
      need(['passed','not_applicable'].includes(c.status), `${c.id}: ${c.status}`);
      if (c.evidence?.startsWith('#evidence/')) need(text(proposal.evidence?.[c.evidence.slice(10)]), 'Falta texto integrado en evidence');
      else need(text(c.evidence) && fs.statSync(safe(folder, c.evidence)).size > 0, 'Ruta relativa al borrador o #evidence/clave');
    });
    check('blocking_issues', () => need(Array.isArray(proposal.blocking_issues) && !proposal.blocking_issues.length, 'Incidencias bloqueantes abiertas'));
    if (proposal.layout_views) check('layout_views', () => layoutViews(folder, proposal));
    if (stage === 'prototipo' && files(folder).some(f => f.endsWith('.html'))) check('geometry', () => checkedLayout(data, folder, proposal));
    if (stage === 'prototipo' && data.context.workflow_policy === 'rapid') check('independent_review',()=>{
      const event=data.events.findLast(e=>e.type==='independent_review_recorded' && e.source_sha256===layoutDigest(folder));
      need(event?.report.passed === true && event.report.blocking_issues.length===0,'Falta ui_review_record de ui/review completado sobre el hash actual');
    });
    check('figma', () => {
      requireExportList(data.context, stage, proposal, folder);
      if (fs.existsSync(safe(folder, 'figma.json'))) { validateFigmaManifest(read(safe(folder,'figma.json')), task); need(checks.get('figma_mapping')?.status === 'passed', 'Falta figma_mapping passed'); }
      for (const [i, item] of (proposal.figma_exports ?? []).entries()) {
        need(typeof item.file === 'string' && /^[A-Za-z0-9_-][A-Za-z0-9_./-]*\.html$/.test(item.file) && !item.file.split('/').includes('..'), `figma_exports[${i}].file: relativo al borrador, ejemplo resumen.html`);
        need(text(item.screen) && text(item.state) && Number.isInteger(item.viewport?.width) && item.viewport.width > 0 && Number.isInteger(item.viewport?.height) && item.viewport.height > 0, `figma_exports[${i}]: screen/state y viewport {width,height} positivos`);
        fs.statSync(safe(folder,item.file));
      }
    });
    return { ready: errors.length === 0, errors, next: errors.length ? 'Corrige todos los campos; no repitas submit ni delegues depuración del motor.' : 'Listo para submit; no concede aprobación.' };
  }
  function prepare(task, stage, metadata = {}) {
    need(profile === 'ui' && stages.includes(stage), 'Preparación solo de Interfaz');
    return locked(task, () => {
      const data = load(task); need(activeStages(data.context).includes(stage), 'Etapa no requerida por el flujo');
      const folder = safe(data.folder,'drafts',stage), file = safe(folder,'proposal.json');
      const old = fs.existsSync(file) ? parseUniqueJSON(fs.readFileSync(file,'utf8')) : {};
      const required = ['prototipo','entrega'].includes(stage) ? [...CHECKS,...Object.keys(data.context.criteria),'scope_review','independent_review'] : stage === 'visual' ? ['contrast'] : [];
      const checks = [...(old.checks ?? [])];
      for (const id of required) if (!checks.some(c => c.id === id)) checks.push({ id, status: 'pending', evidence: `#evidence/${id}` });
      const proposal = { format: 2, summary: data.context.objective, change_reason: data.current[stage] ? 'Iteración de la propuesta' : 'Primera propuesta',
        instruction_ref: metadata.instruction_ref ?? '', model: metadata.model ?? '', synthetic_data: true,
        inputs: ['context.json'], source_files: [], evidence: {}, blocking_issues: [], open_questions: [], scope_change: null,
        ...old, ...(metadata.model ? {model:metadata.model} : {}), session_ref: metadata.sessionID ? `opencode-session:${metadata.sessionID}` : old.session_ref ?? '', checks };
      proposal.source_files = (proposal.source_files ?? []).filter(source => {
        if (!text(source) || path.isAbsolute(source)) return true; // Validation retains forbidden inputs; never normalize them into permission.
        const resolved=safe(source);
        return resolved!==folder && !resolved.startsWith(folder+path.sep)
          && !(fs.existsSync(safe(folder,source)) && fs.statSync(safe(folder,source)).isFile());
      });
      for (const c of checks) if (c.evidence?.startsWith('#evidence/')) proposal.evidence[c.evidence.slice(10)] ??= 'Pendiente de comprobar; no acredita ejecución';
      fs.writeFileSync(file, JSON.stringify(proposal,null,2)+'\n');
      return { file: path.relative(root,file), required_checks: required, capabilities: { registry: 'laid-ui', build_and_measure: 'ui/prototype', independent_review: 'ui/review', publish: 'ui/figma' },
        next: 'Completa contenido, modelo real, scope_change y evidencia; usa ui_preflight antes de submit. No se ha congelado ni aprobado.' };
    });
  }
  function projectContext() {
    need(profile === 'ui','Solo Interfaz');
    const projectFile = safe('.laid','ui-project.json'), trackerFile = safe('.laid','backlog-project.json');
    const project = fs.existsSync(projectFile) ? read(projectFile) : null;
    const tracker = fs.existsSync(trackerFile) ? read(trackerFile).tracker : null;
    return { project: project ? Object.fromEntries(['agreement_ref','data_policy','owner','mode','review_policy','workflow_policy','purpose','approvers','visual_sources','constraints'].filter(k => project[k] !== undefined).map(k => [k,project[k]])) : null,
      tracker: tracker ? { adapter: tracker.adapter, project: tracker.project } : null,
      instructions_file: fs.existsSync(safe('AGENTS.md')) ? 'AGENTS.md' : null,
      capabilities: { 'laid-ui': ['ui_start','ui_checkpoint','ui_prepare','ui_preflight','init','submit','request_review','status'],
        'ui/prototype': ['ui_checkpoint','ui_preview','ui_measure','ui_check','ui_geometry','figma_build','figma_validate','edit own draft'],
        'ui/review': ['ui_preview','ui_geometry','read only'], 'ui/figma': ['figma_connect','figma_publish','figma_status'] },
      next: 'Elegir fuente por encargo; tracker configurado no autoriza consultar Jira automáticamente. Reutilizar contexto y contrato.' };
  }
  function recordReview(task,sessionID,messageID,report) {
    need(profile==='ui' && text(sessionID) && text(messageID),'Sesión/mensaje de revisión ausentes');
    return locked(task,()=>{
      const data=load(task), folder=safe(data.folder,'drafts','prototipo');
      need(object(report) && report.source_sha256===layoutDigest(folder) && typeof report.passed==='boolean'
        && Array.isArray(report.blocking_issues) && text(report.evidence)
        && (!report.passed || report.blocking_issues.length===0),'Informe de revisión incompleto u obsoleto');
      const event=append(data.folder,data.events,{type:'independent_review_recorded',sessionID,messageID,source_sha256:report.source_sha256,report});
      const file=safe(folder,'proposal.json'), proposal=read(file);
      proposal.evidence ??={};proposal.evidence.independent_review=`opencode-session:${sessionID}#${messageID}\n${report.evidence}`;
      proposal.checks=[...(proposal.checks??[]).filter(c=>c.id!=='independent_review'),{id:'independent_review',status:report.passed?'passed':'failed',evidence:'#evidence/independent_review'}];
      fs.writeFileSync(file,JSON.stringify(proposal,null,2)+'\n');
      return {seq:event.seq,passed:report.passed,blocking_issues:report.blocking_issues};
    });
  }
  function start(task, input, metadata) {
    need(profile === 'ui' && object(input) && text(input.story) && text(input.objective)
      && object(input.criteria) && Object.keys(input.criteria).length > 0, 'Intake: story, objective, criteria obligatorios');
    const folder=taskPath(task);
    if (fs.existsSync(safe(folder,'events.jsonl'))) return {resumed:true,checkpoint:checkpoint(task,metadata)};
    const intake=safe('.laid','intake',task,'context-input.json');
    fs.mkdirSync(path.dirname(intake),{recursive:true});
    if (fs.existsSync(intake)) need(JSON.stringify(read(intake))===JSON.stringify(input),'Intake existente diferente: revisar, no sobrescribir');
    else write(intake,input);
    init(task); prepare(task,'prototipo',metadata);
    return {resumed:false,checkpoint:checkpoint(task,metadata)};
  }
  function checkpoint(task, metadata={}) {
    need(profile==='ui','Checkpoint solo de Interfaz');
    const data=load(task), folder=safe(data.folder,'drafts','prototipo');
    const elapsed=Math.max(0,Math.round((Date.now()-(metadata.started_at??Date.parse(data.events[0].at)))/1000));
    let plan; try {plan=measurementPlan(task);} catch(error){plan={pending_setup:error.message};}
    const budget=(data.context.budget_minutes??25)*60;
    const browser=data.events.findLast(e=>e.type==='browser_checked'&&(e.render_sha256?e.render_sha256===browserStamp(folder):e.source_sha256===layoutStamp(task)));
    return {task,source_sha256:layoutStamp(task),context_file:path.relative(root,safe(data.folder,'context.json')),
      files:files(folder).filter(f=>!path.relative(folder,f).replaceAll('\\','/').startsWith('evidence/')).map(f=>({file:path.relative(folder,f).replaceAll('\\','/'),bytes:fs.statSync(f).size,sha256:sha(fs.readFileSync(f))})),
      geometry:plan,browser:browser?{seq:browser.seq,passed:browser.report.passed}:null,
      figma_prepared:fs.existsSync(safe(folder,'figma.json')),
      budget:{elapsed_wall_seconds:elapsed,limit_seconds:budget,exhausted:elapsed>=budget,note:'Tiempo de sesión incluye esperas, no tiempo activo'},
      next:elapsed>=budget?'Devuelve preview y pendientes al principal; no reconstruyas ni declares éxito.':
        'Lee los archivos existentes y completa únicamente pendientes; no reescribas un prototipo ya construido. No solicita aprobación ni publica.'};
  }
  function buildFigma(task) {
    return locked(task,()=>{
      const data=load(task), folder=safe(data.folder,'drafts','prototipo');
      const value=materializeFigma(parseUniqueJSON(fs.readFileSync(safe(folder,'figma.source.json'),'utf8')),task);
      fs.writeFileSync(safe(folder,'figma.json'),JSON.stringify(value,null,2)+'\n');
      return {file:'.laid/ui/'+task+'/drafts/prototipo/figma.json',roots:value.nodes.length,valid:true,
        next:'Revisar correspondencia HTML/Figma; validación no acredita fidelidad ni publica.'};
    });
  }
  function recordBrowser(task,sessionID,report,source_sha256) {
    return locked(task,()=>{
      const data=load(task);need(text(sessionID)&&source_sha256===layoutStamp(task)&&Array.isArray(report.scenarios),'Pruebas de navegador incompletas u obsoletas');
      const event=append(data.folder,data.events,{type:'browser_checked',sessionID,source_sha256,render_sha256:browserStamp(safe(data.folder,'drafts','prototipo')),report});
      return {seq:event.seq,...report,next:'Conserva estas pruebas por hash; no concede aprobación ni revisión independiente.'};
    });
  }
  function browserPlan(task) {
    const folder=safe(taskPath(task),'drafts','prototipo');return read(safe(folder,'proposal.json')).interaction_checks;
  }
  function browserStamp(folder) {
    return sha(JSON.stringify(files(folder).filter(f=>{
      const name=path.relative(folder,f).replaceAll('\\','/');
      return !name.startsWith('evidence/')&&!name.startsWith('_agent-context/')&&!name.endsWith('.md')&&!['proposal.json','figma.json','figma.source.json'].includes(name);
    }).map(f=>[path.relative(folder,f),sha(fs.readFileSync(f))])));
  }
  return { createProject, init, submit, requestReview, sync, status, list, begin, record, inspect, dispatch, cancel, figmaFiles, figmaBegin, figmaReport, figmaReconcile, layoutStamp, recordLayout, layoutView, measurementPlan, preflight, prepare, projectContext, recordReview, start, checkpoint, buildFigma, recordBrowser, browserPlan };
}

