// Perfil de Backlog; el registro y las decisiones siguen en workflow.mjs.
export const BACKLOG_STAGES = ['encargo', 'refinamiento', 'entrega'];
export const BACKLOG_CHECKS = ['source_traceability', 'acceptance_verifiable', 'coverage',
  'dependencies', 'dor_dod', 'execution_modes', 'independent_review', 'handoff'];
const text = v => typeof v === 'string' && v.trim().length > 0;
const need = (ok, message) => { if (!ok) throw new Error(`Backlog: ${message}`); };

export function validateBacklog(value, stage) {
  need(value && typeof value === 'object' && !Array.isArray(value), 'paquete inválido');
  need(!JSON.stringify(value).includes('SUSTITUIR'), 'paquete incompleto');
  for (const key of ['story', 'objective', 'description']) need(text(value[key]), `falta ${key}`);
  need(Array.isArray(value.sources) && value.sources.length > 0 && value.sources.every(text), 'faltan fuentes');
  for (const key of ['criteria', 'tasks', 'dor', 'dod']) {
    need(Array.isArray(value[key]) && value[key].length > 0, `falta ${key}`);
    const ids = new Set();
    for (const item of value[key]) {
      need(item && text(item.id) && !ids.has(item.id), `${key}: ID vacío o duplicado`);
      ids.add(item.id);
    }
  }
  const criteria = new Set(value.criteria.map(c => c.id));
  for (const c of value.criteria) need(text(c.text) && text(c.verification), 'criterio sin resultado/verificación');
  const tasks = new Map(value.tasks.map(t => [t.id, t]));
  const covered = new Set();
  for (const task of value.tasks) {
    for (const key of ['objective', 'output', 'owner_role', 'rationale', 'review'])
      need(text(task[key]), `${task.id}: falta ${key}`);
    need(['manual', 'asistida', 'mixta', 'agente'].includes(task.mode), `${task.id}: modo inválido`);
    need(typeof task.manual_only === 'boolean' && (!task.manual_only || task.mode === 'manual'), `${task.id}: zona manual`);
    for (const key of ['objective_acceptance', 'automatable', 'explicit_contract', 'deterministic'])
      need(text(task.rubric?.[key]), `${task.id}: rúbrica incompleta`);
    need(Array.isArray(task.criteria) && task.criteria.length > 0
      && task.criteria.every(id => criteria.has(id)), `${task.id}: referencia a criterio inválida`);
    task.criteria.forEach(id => covered.add(id));
    need(Array.isArray(task.depends_on) && task.depends_on.every(id => tasks.has(id)), `${task.id}: dependencia inexistente`);
  }
  need([...criteria].every(id => covered.has(id)), 'criterios sin cobertura');
  const visiting = new Set(), visited = new Set();
  function visit(id) {
    need(!visiting.has(id), 'dependencia circular');
    if (visited.has(id)) return;
    visiting.add(id);
    tasks.get(id).depends_on.forEach(visit);
    visiting.delete(id); visited.add(id);
  }
  tasks.forEach((_, id) => visit(id));
  for (const key of ['dor', 'dod']) for (const item of value[key]) {
    need(text(item.text) && text(item.evidence)
      && ['passed', 'failed', 'pending', 'not_applicable'].includes(item.status), `${key}: condición sin estado/evidencia`);
    if (key === 'dor' && stage === 'entrega')
      need(['passed', 'not_applicable'].includes(item.status), 'DoR pendiente o fallida');
  }
  for (const id of ['acceptance_tests', 'human_review', 'coverage', 'documentation', 'po_validation'])
    need(value.dod.some(item => item.id === id && item.status !== 'not_applicable'), `DoD sin mínimo LAID: ${id}`);
}

