const text = v => typeof v === 'string' && v.trim().length > 0;
const object = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const need = (ok, message) => { if (!ok) throw new Error(`Tablero: ${message}`); };
export const BOARD_ACTIONS = ['create', 'update', 'transition', 'close', 'reopen', 'link',
  'comment', 'comment_edit', 'comment_delete', 'assign', 'prioritize', 'sprint', 'sprint_start', 'sprint_close', 'archive', 'delete', 'attachment'];

export function validateOperation(op, context) {
  need(object(op) && !JSON.stringify(op).includes('SUSTITUIR'), 'operación incompleta');
  need(BOARD_ACTIONS.includes(op.action), 'acción no admitida');
  for (const key of ['operation_id', 'reason', 'source_ref', 'expected_updated']) need(text(op[key]), `falta ${key}`);
  need(op.expected_updated !== '*', 'precondición remota no puede ser un comodín');
  need(object(op.target) && ['epic', 'story', 'task', 'bug', 'subtask', 'sprint', 'board'].includes(op.target.kind)
    && text(op.target.project) && text(op.target.id), 'destino incompleto');
  need(op.target.project === context.tracker.project, 'proyecto fuera del alcance');
  need(object(op.changes) && Object.keys(op.changes).length > 0, 'faltan cambios concretos');
  need(typeof op.reaches_done === 'boolean', 'declarar si alcanza Hecho');
  if (['sprint_start', 'sprint_close'].includes(op.action)) need(op.target.kind === 'sprint' && !op.reaches_done,
    'gestionar el sprint no marca tareas Hechas');
  need(Array.isArray(op.evidence) && op.evidence.length > 0 && op.evidence.every(text), 'faltan evidencias');
  need(object(op.ai_usage) && ['manual', 'asistida', 'mixta', 'agente'].includes(op.ai_usage.mode), 'modo IA inválido');
  need(op.ai_usage.mode === context.execution_mode, 'modo del elemento distinto al contexto');
  const usage = op.ai_usage;
  need(usage.percent === null || (typeof usage.percent === 'number' && Number.isFinite(usage.percent)
    && usage.percent >= 0 && usage.percent <= 100), 'porcentaje IA debe ser null o 0–100');
  if (usage.percent !== null) {
    for (const key of ['basis', 'source_ref', 'declared_by', 'measured_at']) need(text(usage[key]), `porcentaje sin ${key}`);
    need(Number.isFinite(Date.parse(usage.measured_at)), 'fecha de medición inválida');
    need(usage.mode !== 'manual' || usage.percent === 0, 'modo manual incompatible con porcentaje positivo');
  }
  if (op.action === 'create') {
    need(['epic', 'story', 'task', 'bug', 'subtask'].includes(op.target.kind) && !op.reaches_done, 'alta de elemento inválida');
    need(text(op.changes.title) && text(op.changes.description), 'alta sin título/descripción');
    if (op.target.kind === 'subtask') need(text(op.changes.parent?.key), 'subtarea sin padre');
    if (op.target.kind === 'story') need(Array.isArray(op.changes.acceptance_criteria)
      && op.changes.acceptance_criteria.length > 0 && op.changes.acceptance_criteria.every(text), 'historia sin aceptación');
  }
  if (['comment', 'comment_edit', 'comment_delete'].includes(op.action)) {
    const deleting = op.action === 'comment_delete', existing = op.action !== 'comment';
    need(!op.reaches_done && Object.keys(op.changes).length === (deleting || !existing ? 1 : 2)
      && (!existing || text(op.changes.comment_id))
      && (deleting || (text(op.changes.comment) && op.changes.comment.length <= 10000)),
    'comentario inválido; ID real para editar/borrar y texto de hasta 10.000 caracteres para añadir/editar');
  }
  // El cierre registra una declaración humana, no certifica las pruebas del producto.
  if (op.action === 'close') need(op.reaches_done, 'close debe alcanzar Hecho');
}

export function validateReceipt(receipt) {
  need(object(receipt) && ['succeeded', 'failed', 'partial', 'unknown'].includes(receipt.status), 'resultado inválido');
  for (const key of ['operation_id', 'attempt', 'summary', 'tool_ref']) need(text(receipt[key]), `resultado sin ${key}`);
  need(Array.isArray(receipt.items) && Array.isArray(receipt.pending), 'resultado sin items/pendientes');
  if (receipt.status === 'succeeded') need(receipt.items.length > 0 && receipt.pending.length === 0
    && receipt.items.every(i => object(i) && text(i.id) && text(i.url) && text(i.readback_ref)), 'éxito sin relectura');
}

