// Shared measurements: browser DOM and native Figma. No model judgement or dependencies.
export function auditLayout(nodes, viewport) {
  const tolerance = 2, issues = [], warnings = [], groups = [], byID = new Map(nodes.map(n => [n.id, n]));
  let truncated = false;
  const add = (rule, ids, actual, expected, scope = 'geometry') => {
    if (issues.length >= 500) { truncated = true; return; }
    issues.push({ rule, scope, nodes: ids, actual, expected, severity: 'major' });
  };
  const right = n => n.x + n.width, bottom = n => n.y + n.height;
  const inside = (a, b, x = true, y = true) => (!x || (a.x >= b.x - tolerance && right(a) <= right(b) + tolerance))
    && (!y || (a.y >= b.y - tolerance && bottom(a) <= bottom(b) + tolerance));
  const exception = (n, rule) => n.exceptions?.includes(rule) && typeof n.reason === 'string' && n.reason.trim().length >= 8;
  for (const n of nodes) {
    if (![n.x, n.y, n.width, n.height].every(Number.isFinite) || n.width < 0 || n.height < 0) {
      add('invalid_measurement', [n.id], 'Invalid bounds', 'Finite non-negative dimensions'); continue;
    }
    if (n.exceptions?.length && !n.reason?.trim()) add('exception_without_reason', [n.id], n.exceptions, 'Document the design reason');
    if (n.measurementError) add('measurement_unavailable', [n.id], n.measurementError, 'Obtain real rendered text measurements');
    const parent = byID.get(n.parent);
    const geometryBounds = n.renderBounds ? { x: Math.min(n.x, n.renderBounds.x), y: n.y,
      width: Math.max(right(n), right(n.renderBounds)) - Math.min(n.x, n.renderBounds.x),
      height: n.height } : n;
    if (parent && !inside(geometryBounds, parent, !exception(n, 'overflow-x'), !parent.scrollY && !n.inline && !exception(n, 'overflow-y'))) {
      if(n.decoration && parent.clip) warnings.push({rule:'decorative_overflow',nodes:[n.id,parent.id],reason:'Non-interactive decoration intentionally clipped by container'});
      else add('container_overflow', [n.id, parent.id], { x: n.x, y: n.y, width: n.width, height: n.height }, 'Keep content within its container; do not hide essential content');
    }
    if (n.textBounds && !inside(n.textBounds, n.textClipBox || n) && !exception(n, 'text-clip'))
      add('text_clipped', [n.id], n.textBounds, 'Fit complete text inside the allocated text box');
    if (n.textOverflow && !exception(n, 'text-clip')) add('text_clipped', [n.id], n.textOverflow, 'Allow text to wrap or grow');
    if (n.role === 'field' && !n.anchor) add('field_without_control_measurement', [n.id], 'Missing control bounds', 'Measure the actual input, independently of label and help text', 'harmony');
  }
  const parents = new Map();
  for (const n of nodes) { if (!parents.has(n.parent)) parents.set(n.parent, []); parents.get(n.parent).push(n); }
  const range = values => Math.max(...values) - Math.min(...values);
  for (const [parentID, siblings] of parents) {
    const parent = byID.get(parentID);
    if (!parent) continue;
    const comparable = siblings.filter(n => ['card', 'field', 'control', 'button'].includes(n.role));
    const axis = parent.axis || (comparable.length > 1
      ? (comparable.some((a, i) => comparable.slice(i + 1).some(b => Math.min(bottom(a), bottom(b)) - Math.max(a.y, b.y) > tolerance)) ? 'row' : 'column') : undefined);
    if (!['row', 'grid', 'column'].includes(axis)) continue;
    const families = new Map();
    for (const n of siblings) {
      if (!['card', 'field', 'control', 'button'].includes(n.role)) continue;
      const key = n.peerGroup || `${n.role}:${n.peerVariant??''}`;
      if (!families.has(key)) families.set(key, []); families.get(key).push(n);
    }
    for (const peers of families.values()) {
      // ponytail: sibling grouping only, not a global aesthetic score; explicit peerGroup handles unusual layouts.
      const rows = [];
      for (const n of peers.sort((a, b) => a.y - b.y || a.x - b.x)) {
        const row = axis === 'column' ? rows[0] : rows.find(r => r.some(p => Math.min(bottom(n), bottom(p)) - Math.max(n.y, p.y) > tolerance));
        if (row) row.push(n); else rows.push([n]);
      }
      for (const row of rows.filter(r => r.length > 1)) {
        const horizontal = axis !== 'column', boxes = row.map(n => n.anchor || n), ids = row.map(n => n.id);
        groups.push({ parent: parentID, nodes: ids, axis: horizontal ? 'row' : 'column', role: row[0].role });
        const aligned = row.filter(n => !exception(n, 'alignment'));
        if (aligned.length > 1) {
          const positions = aligned.map(n => horizontal ? (n.anchor || n).y : (n.anchor || n).x);
          if (range(positions) > tolerance) add('peer_alignment', aligned.map(n => n.id), positions, `Same ${horizontal ? 'top' : 'left'} edge within ${tolerance}px`, 'harmony');
        }
        if (horizontal && ['card', 'field', 'control', 'button'].includes(row[0].role)) {
          const equal = row.filter(n => !exception(n, 'equal-height')), heights = equal.map(n => (n.anchor || n).height);
          if (equal.length > 1 && range(heights) > tolerance) add('peer_height', equal.map(n => n.id), heights, `Equal peer heights within ${tolerance}px`, 'harmony');
        }
        if (!horizontal) {
          const equal = row.filter(n => !exception(n, 'equal-width')), widths = equal.map(n => (n.anchor || n).width);
          if (equal.length > 1 && range(widths) > tolerance) add('peer_width', equal.map(n => n.id), widths, `Equal peer widths within ${tolerance}px`, 'harmony');
        }
        const padding = row.filter(n => Array.isArray(n.padding) && !exception(n, 'spacing'));
        if (padding.length > 1 && [0, 1, 2, 3].some(i => range(padding.map(n => n.padding[i])) > tolerance))
          add('peer_padding', padding.map(n => n.id), padding.map(n => n.padding), 'Consistent padding among equivalent peers', 'harmony');
        for (let i = 0; i < row.length; i++) for (let j = i + 1; j < row.length; j++) {
          const a = boxes[i], b = boxes[j];
          if (Math.min(right(a), right(b)) - Math.max(a.x, b.x) > tolerance
            && Math.min(bottom(a), bottom(b)) - Math.max(a.y, b.y) > tolerance
            && !exception(row[i], 'overlap') && !exception(row[j], 'overlap'))
            add('peer_overlap', [row[i].id, row[j].id], { a, b }, 'Separate equivalent interactive/content elements');
        }
      }
    }
  }
  const geometry = issues.filter(i => i.scope === 'geometry'), harmony = issues.filter(i => i.scope === 'harmony');
  return { format: 1, engine: 'laid-layout-v1', viewport, measured_nodes: nodes.length, groups, truncated, warnings,
    geometry: { passed: geometry.length === 0, issues: geometry }, harmony: { passed: harmony.length === 0, issues: harmony },
    passed: issues.length === 0, issues, exceptions: nodes.filter(n => n.exceptions?.length).map(n => ({ node: n.id, rules: n.exceptions, reason: n.reason })),
    next: issues.length ? 'Correct the measured draft and rerun all states/viewports; do not approve or hide overflow.' : 'Ready for independent visual review; this is not an aesthetic or accessibility certificate.' };
}

export function measureDOM() {
  const viewport = { width: innerWidth, height: innerHeight }, nodes = [], ids = new Map();
  const elements = [...document.body.querySelectorAll('*')].filter(el => !['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE'].includes(el.tagName));
  const rect = el => { const r = el.getBoundingClientRect(); return { x: r.x, y: r.y, width: r.width, height: r.height }; };
  const visible = el => {
    for (let parent = el.parentElement; parent; parent = parent.parentElement) {
      if (parent.tagName === 'DETAILS' && !parent.open) {
        const summary = parent.querySelector(':scope > summary');
        if (!summary || !summary.contains(el)) return false;
      }
    }
    const s = getComputedStyle(el), r = rect(el); return s.display !== 'none' && s.visibility !== 'hidden' && Number(s.opacity) !== 0 && r.width > 0 && r.height > 0
    && !(r.width <= 2 && r.height <= 2 && (s.clip !== 'auto' || s.clipPath !== 'none')) && !el.classList.contains('skip-link') && !el.classList.contains('sr-only'); };
  ids.set(document.body, 'body');
  nodes.push({ id: 'viewport', x: 0, y: 0, width: innerWidth, height: innerHeight });
  nodes.push({ id: 'body', ...rect(document.body), x: 0, width: innerWidth, scrollY: true });
  const selectors=new Map([[document.body,'body']]);
  for (const el of elements) {
    const siblings=[...(el.parentElement?.children??[])].filter(n=>n.tagName===el.tagName);
    const selector=el.id?`#${CSS.escape(el.id)}`:`${selectors.get(el.parentElement)??'body'} > ${el.tagName.toLowerCase()}:nth-of-type(${siblings.indexOf(el)+1})`;
    selectors.set(el,selector);if(visible(el))ids.set(el,selector);
  }
  for (const el of elements.filter(el => ids.has(el))) {
    const style = getComputedStyle(el), bounds = rect(el);
    let parent = el.parentElement; while (parent && !ids.has(parent)) parent = parent.parentElement;
    const controls = [...el.querySelectorAll('input:not([type=hidden]),select,textarea')].filter(visible);
    const ownControl = ['INPUT', 'SELECT', 'TEXTAREA'].includes(el.tagName);
    const field = !ownControl && controls.length === 1 && ['INPUT', 'SELECT', 'TEXTAREA'].includes(controls[0].tagName)
      && (el.classList.contains('field') || el.classList.contains('form-group') || el.dataset.laidRole === 'field' || el.tagName === 'LABEL' || el.querySelector(':scope > label'));
    const role = el.dataset.laidRole || (ownControl ? 'control' : field ? 'field'
      : /(?:^|[-_\s])(?:card|tarjeta)(?:$|[-_\s])/i.test(el.className?.toString() || '') ? 'card' : el.tagName === 'BUTTON' ? 'button' : undefined);
    const node = { id: ids.get(el), parent: ids.get(parent), ...bounds, role,
      axis: style.display.includes('flex') ? (style.flexDirection.startsWith('column') ? 'column' : 'row') : style.display.includes('grid') ? 'grid' : undefined,
      scrollY: ['auto', 'scroll'].includes(style.overflowY), padding: ['Top', 'Right', 'Bottom', 'Left'].map(k => parseFloat(style[`padding${k}`]) || 0),
      inline:style.display==='inline',clip:['hidden','clip'].includes(style.overflowX)||['hidden','clip'].includes(style.overflowY),
      decoration:el.getAttribute('aria-hidden')==='true'&&!el.matches('button,a[href],input,select,textarea,[tabindex]')&&!el.querySelector('button,a[href],input,select,textarea,[tabindex]')&&!el.textContent.trim(),
      peerVariant:el.dataset.laidVariant||(role==='button'?(el.className?.toString().match(/(?:btn|button)[-_](primary|secondary|text|link)\b/)?.[1]):undefined),
      peerGroup: el.dataset.laidPeers, exceptions: el.dataset.laidExceptions?.split(',').map(s => s.trim()), reason: el.dataset.laidReason,
      ...(field ? { anchor: rect(controls[0]) } : {}) };
    if (style.position === 'fixed') node.parent = 'viewport';
    if (!ownControl && !el.children.length && el.textContent.trim()) {
      const range = document.createRange(); range.selectNodeContents(el); const r = range.getBoundingClientRect();
      node.renderBounds = { x: r.x, y: r.y, width: r.width, height: r.height };
      let clip = el;
      while (clip && !['hidden', 'clip'].includes(getComputedStyle(clip).overflowX) && !['hidden', 'clip'].includes(getComputedStyle(clip).overflowY)) clip = clip.parentElement;
      if (clip) { node.textBounds = node.renderBounds; node.textClipBox = rect(clip); }
      if (clip === el && el.clientWidth > 0 && (el.scrollWidth > el.clientWidth + 2 || el.scrollHeight > el.clientHeight + 2))
        node.textOverflow = { width: el.scrollWidth - el.clientWidth, height: el.scrollHeight - el.clientHeight };
    }
    nodes.push(node);
  }
  return auditLayout(nodes, viewport);
}

export function measureFigma(roots, api) {
  const frames = [];
  const bounds = node => {
    const r = node.absoluteBoundingBox;
    return r ? { x: r.x, y: r.y, width: r.width, height: r.height } : { x: node.x || 0, y: node.y || 0, width: node.width, height: node.height };
  };
  const metadata = node => { try { return JSON.parse(node.getPluginData('laid:layout') || '{}'); } catch { return {}; } };
  const descendants = node => (node.children || []).flatMap(child => [child, ...descendants(child)]);
  const components = new Map(roots.flatMap(root => [root, ...descendants(root)]).filter(n => n.type === 'COMPONENT')
    .map(n => [n.getPluginData('laid:id'), n]));
  const role = node => {
    const meta = metadata(node), component = node.type === 'INSTANCE' ? components.get(node.getPluginData('laid:component')) : undefined;
    const name = `${node.name} ${component?.name || ''}`;
    return meta.role || (component && metadata(component).role) || (/campo|\bfield\b/i.test(name) ? 'field'
      : /tarjeta|\bcard\b/i.test(name) ? 'card' : /entrada|\binput\b|\bcontrol\b/i.test(name) ? 'control'
        : /botón|\bbutton\b/i.test(name) ? 'button' : undefined);
  };
  for (const root of roots) {
    const measured = [];
    const visit = (node, parent) => {
      if (node.visible === false) return;
      const meta = metadata(node), r = bounds(node), nodeRole = role(node);
      const control = nodeRole === 'field' ? descendants(node).find(n => role(n) === 'control') : undefined;
      const value = { id: node.id, parent, ...r, role: nodeRole, peerGroup: meta.peerGroup,
        exceptions: meta.exceptions, reason: meta.reason, anchor: control ? bounds(control) : undefined,
        axis: node.layoutMode === 'HORIZONTAL' ? 'row' : node.layoutMode === 'VERTICAL' ? 'column' : undefined,
        scrollY: node.overflowDirection === 'VERTICAL_SCROLLING',
        padding: [node.paddingTop || 0, node.paddingRight || 0, node.paddingBottom || 0, node.paddingLeft || 0] };
      if (node.type === 'TEXT' && node.characters) {
        let probe;
        try {
          probe = api.createText(); probe.fontName = node.fontName; probe.fontSize = node.fontSize;
          probe.characters = node.characters; probe.lineHeight = node.lineHeight; probe.letterSpacing = node.letterSpacing;
          probe.paragraphSpacing = node.paragraphSpacing || 0; probe.textAutoResize = 'HEIGHT';
          probe.resize(Math.max(1, node.width), Math.max(1, node.height));
          if (!Number.isFinite(probe.height)) throw new Error('Native text metrics unavailable');
          if (probe.height > node.height + 2) value.textOverflow = { required_height: probe.height, actual_height: node.height };
        } catch (error) { value.measurementError = String(error); }
        finally { if (typeof probe?.remove === 'function') probe.remove(); }
      }
      measured.push(value); for (const child of node.children || []) visit(child, node.id);
    };
    visit(root);
    frames.push({ node: root.id, name: root.name, report: auditLayout(measured, { width: root.width, height: root.height }) });
  }
  return { engine: 'laid-layout-v1', source: 'figma', passed: frames.every(f => f.report.passed), frames,
    issues: frames.flatMap(f => f.report.issues.map(issue => ({ ...issue, frame: f.node, screen: f.name }))) };
}

