import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import { randomUUID } from 'node:crypto';

export function prototypePreview(ctx, flow, options = {}) {
  const servers = new Map();
  const rounds = new Map();
  let inFlight;
  const decode = result => {
    if (result.isError || result.metadata?.truncated) throw new Error('Navegador: resultado fallido o truncado');
    const output=result.structuredContent??result.output??result.content;
    if(output&&typeof output==='object'&&!Array.isArray(output))return output;
    const raw=typeof output==='string'?output:Array.isArray(output)?output.filter(c=>c.type==='text').map(c=>c.text).join('\n'):'';
    return JSON.parse(/### Result\s*\n([\s\S]*?)(?:\n### |$)/.exec(raw)?.[1]?.trim()??raw);
  };
  async function run(remote,args,tool) {
    if(tool.signal.aborted)throw new Error('Operación cancelada');
    if(inFlight)throw new Error('Navegador ocupado tras timeout; espera recuperación, no lanzar otro lote');
    const controller=new AbortController();const cancel=()=>controller.abort();tool.signal.addEventListener('abort',cancel,{once:true});
    let timer;
    const promise=Promise.resolve().then(()=>remote.execute(args,{...tool,signal:controller.signal}));inFlight=promise;
    promise.then(()=>{if(inFlight===promise)inFlight=undefined;},()=>{if(inFlight===promise)inFlight=undefined;});
    try{const result=await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(new Error('Navegador: deadline; devuelve avance parcial, no reintentes a ciegas'));},options.operationTimeout??12000);})]);if(result.isError)throw new Error('Navegador: operación fallida');return result;}
    finally{clearTimeout(timer);tool.signal.removeEventListener('abort',cancel);}
  }
  async function open(task, tool) {
    if (!['ui/prototype', 'ui/review'].includes(tool.agent) || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(task))
      throw new Error('Vista previa: agente o tarea inválidos');
    const child = await ctx.session.get({ sessionID: tool.sessionID });
    const parent = child.parentID && await ctx.session.get({ sessionID: child.parentID });
    if (child.agent !== tool.agent || !parent || parent.parentID || parent.agent !== 'laid-ui'
      || [child, parent].some(s => path.resolve(s.location.directory) !== path.resolve(ctx.location.directory)))
      throw new Error('Vista previa: delegación o proyecto incorrectos');
    if (tool.signal.aborted) throw new Error('Operación cancelada');
    const root = fs.realpathSync(ctx.location.directory);
    const folder = fs.realpathSync(path.join(root, '.laid/ui', task, 'drafts/prototipo'));
    if (!folder.startsWith(root + path.sep)) throw new Error('Vista previa fuera del proyecto');
    if (servers.has(folder)) return { url: servers.get(folder).url, base_url: servers.get(folder).base_url,
      source_sha256: flow?.layoutStamp(task) };
    const entry = ['index.html', 'assets/prototype.html', 'prototype.html'].find(name => fs.existsSync(path.join(folder, name)));
    if (!entry) throw new Error('Falta index.html o prototype.html en el borrador');
    const token = randomUUID();
    const server = http.createServer((req, res) => {
      try {
        const pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
        if (req.method !== 'GET' || !pathname.startsWith(`/${token}/`)) throw new Error('Ruta inválida');
        const relative = pathname.slice(token.length + 2) || entry;
        if (relative.startsWith('evidence/')) throw new Error('Evidencia no ejecutable como recurso del prototipo');
        if (!['.html', '.css', '.js', '.svg', '.png', '.jpg', '.webp'].includes(path.extname(relative))) throw new Error('Tipo no permitido');
        const file = fs.realpathSync(path.resolve(folder, relative));
        if (!file.startsWith(folder + path.sep) || !fs.statSync(file).isFile()) throw new Error('Ruta fuera del prototipo');
        const types = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp' };
        res.writeHead(200, { 'content-type': types[path.extname(file)], 'cache-control': 'no-store', 'x-content-type-options': 'nosniff',
          'content-security-policy': "default-src 'self' data:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'none'" });
        res.end(fs.readFileSync(file));
      } catch { res.writeHead(404); res.end('No disponible'); }
    });
    await new Promise((resolve, reject) => server.once('error', reject).listen(0, '127.0.0.1', resolve));
    server.unref();
    const url = `http://127.0.0.1:${server.address().port}/${token}/${entry}`;
    const base_url = `http://127.0.0.1:${server.address().port}/${token}/`;
    servers.set(folder, { server, url, base_url }); return { url, base_url, source_sha256: flow?.layoutStamp(task) };
  }
  async function audit(task, state, tool) {
    const { url, base_url } = await open(task, tool);
    const prefix = base_url ?? url.slice(0, url.lastIndexOf('/') + 1);
    const view = flow.layoutView?.(task, state);
    const before = flow.layoutStamp(task);
    const remote = (await ctx.tool.list()).find(t => t.id === 'playwright_browser_evaluate');
    if (!remote) throw new Error('Geometría: Playwright no está disponible; comprobación pendiente');
    const code = fs.readFileSync(new URL('./layout-audit.mjs', import.meta.url), 'utf8').replaceAll('export function', 'function');
    const result = await run(remote,{ function: `async () => {
      if (!location.href.startsWith(${JSON.stringify(prefix)})) throw new Error('Solo el prototipo asignado');
      const expected = ${JSON.stringify(view ?? null)};
      if (expected) {
        const file = decodeURIComponent(location.pathname).slice(new URL(${JSON.stringify(prefix)}).pathname.length);
        if (file !== expected.file) throw new Error('Vista incorrecta: abre ' + expected.file);
        if (expected.selector) { const el = document.querySelector(expected.selector), r = el?.getBoundingClientRect();
          if (!el || !r.width || !r.height || getComputedStyle(el).display === 'none' || getComputedStyle(el).visibility === 'hidden') throw new Error('Estado esperado no visible: ' + expected.selector); }
      }
      await document.fonts.ready;
      await Promise.all([...document.images].filter(img => img.getBoundingClientRect().width > 0).map(img => img.decode()));
      ${code}
      const report = measureDOM();
      return { url: location.href, file: decodeURIComponent(new URL(location.href).pathname).slice(new URL(${JSON.stringify(prefix)}).pathname.length), report };
    }` }, tool);
    if (tool.signal.aborted || result.isError || result.metadata?.truncated) throw new Error('Geometría: lectura cancelada, fallida o truncada');
    const value=decode(result);
    if (!value?.url?.startsWith(prefix) || flow.layoutStamp(task) !== before) throw new Error('Geometría: el destino o el borrador cambiaron durante la medición');
    return flow.recordLayout(task, tool.sessionID, { ...value, state, source_sha256: before });
  }
  async function measure(task, tool) {
    const { base_url } = await open(task,tool);
    const session=await ctx.session.get({sessionID:tool.sessionID});
    const checkpoint=session.time?.created&&flow.checkpoint?.(task,{started_at:session.time.created});
    if(checkpoint?.budget.exhausted)return {partial:true,checkpoint,next:checkpoint.next};
    const plan = flow.measurementPlan(task);
    const key=`${tool.sessionID}/${task}`, stamps=rounds.get(key)??new Set(), stamp=flow.layoutStamp(task);
    if(plan.pending.length&&stamps.size>=3&&!stamps.has(stamp))return {partial:true,reports:[],next:'Dos rondas de corrección agotadas: devuelve checkpoint/preview y pendientes al principal, no reconstruyas.'};
    const catalog = await ctx.tool.list();
    const navigate = catalog.find(t => t.id === 'playwright_browser_navigate'), resize = catalog.find(t => t.id === 'playwright_browser_resize');
    if (!navigate || !resize) throw new Error('Falta Playwright navigate/resize; no inventar comprobaciones');
    const reports = [];
    const started=Date.now();
    for (const item of plan.pending) {
      if(Date.now()-started>60000)return {partial:true,reports,next:'Lote supera 60 s; devuelve avance y pendientes, sin aprobación.'};
      if (tool.signal.aborted) throw new Error('Operación cancelada');
      const resized = await run(resize,{ width: item.width, height: item.width === 390 ? 844 : 900 },tool);
      if (resized.isError) throw new Error('No se pudo cambiar viewport');
      const target = new URL(item.file,base_url); target.search = item.query ?? '';
      const opened = await run(navigate,{ url: target.href },tool);
      if (opened.isError) throw new Error('No se pudo abrir la vista asignada');
      reports.push(await audit(task,item.state,tool));
    }
    if(reports.length){stamps.add(stamp);rounds.set(key,stamps);}
    const grouped=new Map();for(const r of reports)for(const issue of r.issues??[]){const key=JSON.stringify([issue.rule,issue.nodes]);if(!grouped.has(key))grouped.set(key,{...issue,views:[]});grouped.get(key).views.push(`${r.state}/${r.viewport.width}`);}
    return { measured: reports.length, reused: plan.reused, reports, findings:[...grouped.values()].slice(0,8),next: 'Corrige hallazgos en conjunto; vuelve a ui_measure. La revisión no repite medidas vigentes.' };
  }
  async function check(task,tool) {
    const {base_url}=await open(task,tool), before=flow.layoutStamp(task), plan=flow.browserPlan(task);
    const session=await ctx.session.get({sessionID:tool.sessionID}), checkpoint=session.time?.created&&flow.checkpoint?.(task,{started_at:session.time.created});
    if(checkpoint?.budget.exhausted)return {partial:true,checkpoint,next:checkpoint.next};
    if(!Array.isArray(plan)||!plan.length||plan.length>8)throw new Error('interaction_checks: 1–8 recorridos declarativos');
    const catalog=await ctx.tool.list(), toolFor=id=>{const t=catalog.find(t=>t.id===id);if(!t)throw new Error('Falta navegador: '+id);return t;};
    // Validate the ENTIRE plan before clicking anything. No JS, URLs or file uploads from the model.
    for(const item of plan){
      if(!/^[A-Za-z0-9_-][A-Za-z0-9_./-]*\.html$/.test(item.file)||item.file.split('/').includes('..')||![320,390,768,1440].includes(item.width)||!Array.isArray(item.steps)||!item.steps.length||item.steps.length>20)throw new Error('Recorrido inválido: file local/width/steps');
      for(const step of item.steps){if(Object.keys(step).length!==1||!['click','key','assert'].includes(Object.keys(step)[0]))throw new Error('Paso: click, key o assert');
        if(step.click!==undefined&&(typeof step.click!=='string'||step.click.length>200))throw new Error('Selector click inválido');
        if(step.key!==undefined&&!['Tab','Shift+Tab','Enter','Space','Escape','ArrowDown','ArrowUp'].includes(step.key))throw new Error('Tecla no admitida');
        if(step.assert&&(typeof step.assert.selector!=='string'||!step.assert.selector||step.assert.selector.length>200||Object.keys(step.assert).some(k=>!['selector','text','visible','focused','attribute','value'].includes(k))
          || !['text','visible','focused','value'].some(k=>step.assert[k]!==undefined)||(step.assert.value!==undefined&&typeof step.assert.attribute!=='string')))throw new Error('Aserción DOM incompleta');}
    }
    const scenarios=[], started=Date.now();let captures=0;
    for(const item of plan){
      const assertions=[];let error;
      try{
        await run(toolFor('playwright_browser_resize'),{width:item.width,height:item.width===390?844:900},tool);
        await run(toolFor('playwright_browser_navigate'),{url:new URL(item.file,base_url).href},tool);
        for(const step of item.steps){
          if(tool.signal.aborted||Date.now()-started>60000)throw new Error('Recorrido cancelado o deadline 60 s');
          if(step.click!==undefined){const r=await run(toolFor('playwright_browser_click'),{target:step.click,element:step.click},tool);if(r.isError)throw new Error('Clic real fallido');}
          else if(step.key!==undefined){const r=await run(toolFor('playwright_browser_press_key'),{key:step.key},tool);if(r.isError)throw new Error('Tecla real fallida');}
          else {const expected=step.assert;const r=await run(toolFor('playwright_browser_evaluate'),{function:`() => {
            if(!location.href.startsWith(${JSON.stringify(base_url)}))throw new Error('Solo prototipo asignado');
            const a=${JSON.stringify(expected)},el=document.querySelector(a.selector),r=el?.getBoundingClientRect();
            const actual={text:el?.textContent?.trim(),visible:!!el&&!!r.width&&!!r.height&&getComputedStyle(el).visibility!=='hidden'&&getComputedStyle(el).display!=='none',focused:el===document.activeElement,value:a.attribute?el?.getAttribute(a.attribute):undefined};
            return {passed:!!el&&['text','visible','focused','value'].filter(k=>a[k]!==undefined).every(k=>actual[k]===a[k]),actual};}`},tool);assertions.push({expected,...decode(r)});}
        }
      }catch(e){error=e.message;}
      let capture;
      if(!error&&item.capture===true&&captures<3){
        const folder=fs.realpathSync(path.join(ctx.location.directory,'.laid/ui',task,'drafts/prototipo')), evidence=path.join(folder,'evidence');
        fs.mkdirSync(evidence,{recursive:true});if(!fs.realpathSync(evidence).startsWith(folder+path.sep))throw new Error('Evidencia fuera del prototipo');
        capture=`evidence/check-${scenarios.length}-${item.width}.png`;
        await run(toolFor('playwright_browser_take_screenshot'),{filename:path.join(folder,capture),type:'png',fullPage:true,scale:'css'},tool);captures++;
      }
      scenarios.push({name:item.name??item.file,width:item.width,assertions,passed:!error&&assertions.length>0&&assertions.every(a=>a.passed),...(capture?{capture}:{}),...(error?{error}:{})});
      if(error)break;
    }
    if(flow.layoutStamp(task)!==before)throw new Error('Borrador cambiado durante pruebas');
    return flow.recordBrowser(task,tool.sessionID,{passed:scenarios.length===plan.length&&scenarios.every(s=>s.passed),scenarios},before);
  }
  return { open, audit, measure, check, close: () => Promise.all([...servers.values()].map(({ server }) => new Promise(resolve => server.close(resolve)))) };
}

