import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { validateOperation } from './board.mjs';

const need = (ok, message) => { if (!ok) throw new Error(`Control Jira: ${message}`); };
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const canonical = x => JSON.stringify(x, function (_, value) {
  return object(value) ? Object.fromEntries(Object.keys(value).sort().map(k => [k, value[k]])) : value;
});
const hash = x => createHash('sha256').update(canonical(x)).digest('hex');
const editable = ['summary', 'description', 'parent', 'issuetype', 'assignee', 'priority'];
const sprintBoard = b => ['scrum', 'simple', 'CMPScrum', 'TMP'].includes(b.type);
const sprintActions = ['sprint', 'sprint_start', 'sprint_close'];
const commentActions = ['comment', 'comment_edit', 'comment_delete'];

// Solo tolera el espaciado editorial observado en el Markdown devuelto por Jira.
// Código/HTML: comparación literal; no eliminar espacios ni líneas de contenido.
function descriptionText(value) {
  if (typeof value !== 'string' || /^(?: {4}|\t| *```| *~~~| *<)/m.test(value)) return value;
  return value.replace(/^(#{1,6} [^\n]+)\n\n(?=\S)/gm, '$1\n').replace(/\n+$/, '');
}

function payload(result) {
  need(result && !result.isError && !result.metadata?.isError && !result.metadata?.error, 'La herramienta devolvió un error');
  need(!result.metadata?.truncated, 'Respuesta truncada; se requiere una lectura completa');
  if (result.output !== undefined) return payload(result.output);
  if (result.structuredContent !== undefined) return payload(result.structuredContent);
  if (typeof result === 'string') {
    let parsed;
    try { parsed = JSON.parse(result); } catch { throw new Error('Control Jira: respuesta no verificable como JSON'); }
    return payload(parsed);
  }
  if (result.content !== undefined) {
    const content = result.content;
    return payload(typeof content === 'string' ? content : content.filter(c => c.type === 'text').map(c => c.text).join('\n'));
  }
  if (Object.hasOwn(result, 'data')) return payload(result.data);
  return result;
}

// Sin caché de consultas. Solo se retienen bases reales para preparar una propuesta.
export function jiraGuard(ctx, board) {
  const observations = new Map();
  const optionReads = new Map();
  // ponytail: exclusión por proyecto en este proceso; Jira no ofrece aquí CAS atómico.
  let writing = false;
  async function owner(tool, write = false) {
    need(tool.agent === (write ? 'backlog/jira' : 'tracker/jira-read'),
      write ? 'Solo el ejecutor Jira puede escribir' : 'Solo el lector Jira compartido puede consultar');
    const child = await ctx.session.get({ sessionID: tool.sessionID });
    need(child.parentID, 'Se requiere una delegación del coordinador');
    const parent = await ctx.session.get({ sessionID: child.parentID });
    const here = s => path.resolve(s.location.directory) === path.resolve(ctx.location.directory);
    // Única delegación admitida: laid-backlog lanzado por laid-dev, que a su vez es principal.
    const root = parent.parentID && await ctx.session.get({ sessionID: parent.parentID });
    need(!root || (parent.agent === 'laid-backlog' && root.agent === 'laid-dev' && !root.parentID && here(root)),
      'Delegación anidada no autorizada');
    need(here(parent) && here(child), 'Sesión de otro proyecto');
    need(child.agent === tool.agent, 'Identidad del conector no verificable');
    need(['laid-ui', 'laid-dev', 'laid-qa', 'laid-backlog'].includes(parent.agent), 'Agente principal no autorizado');
    if (write) need(parent.agent === 'laid-backlog', 'Solo laid-backlog puede ordenar escrituras');
    return child.parentID;
  }
  function tracker() {
    const root = fs.realpathSync(ctx.location.directory);
    const file = fs.realpathSync(path.join(root, '.laid/backlog-project.json'));
    need(file.startsWith(root + path.sep), 'Configuración fuera del proyecto');
    const value = JSON.parse(fs.readFileSync(file, 'utf8')).tracker;
    need(value?.adapter === 'backlog/jira' && /^[A-Z][A-Z0-9_]*$/.test(value.project)
      && typeof value.cloud_id === 'string' && !value.cloud_id.includes('SUSTITUIR'), 'Tracker incompleto');
    return value;
  }
  async function call(name, args, tool) {
    need(!tool.signal.aborted, 'Operación cancelada');
    const remote = (await ctx.tool.list()).find(t => t.id === name);
    need(remote, `Herramienta no disponible: ${name}`);
    // Executor original del MCP, con la misma señal y contexto de la herramienta protegida.
    return await remote.execute(args, tool);
  }
  async function pages(name, params, config, tool) {
    const values = [];
    for (let startAt = 0; startAt < 1000;) {
      const result = payload(await call(name, { cloudId: config.cloud_id, ...params, startAt, maxResults: 50 }, tool));
      const items = result.values ?? result.fields ?? result.issueTypes;
      need(Array.isArray(items), `Catálogo incompleto: ${name}`);
      values.push(...items); startAt += items.length;
      if (result.isLast === true || (Number.isInteger(result.total) && startAt >= result.total)) return values;
      need(items.length > 0, `Paginación incompleta: ${name}`);
    }
    throw new Error('Control Jira: catálogo demasiado grande; acota el tablero antes de continuar');
  }
  async function diagnostics(tool) {
    await owner(tool, false);
    const config = tracker(), ids = new Set((await ctx.tool.list()).map(t => t.id));
    const required = ['getJiraIssue', 'searchJiraIssuesUsingJql', 'listJiraIssueTransitions', 'listJiraStatuses', 'listJiraIssueAssignableUsers', 'listJiraProjectIssueTypesMetadata', 'getJiraCurrentUser', 'createJiraIssue', 'listJiraBoards', 'listJiraBoardSprints', 'getJiraBoardConfig', 'getJiraIssueTypeMetaWithFields', 'editJiraIssue', 'transitionJiraIssue', 'manageJiraSprint', 'listJiraIssueComments', 'addOrEditJiraIssueComment', 'deleteJiraComment'];
    return { project: config.project, tools: Object.fromEntries(required.map(n => [`atlassian_${n}`, ids.has(`atlassian_${n}`)])),
      sprint_configured: Boolean(config.board_id && config.allowed_actions?.includes('sprint')),
      note: 'Diagnóstico del catálogo del SDK; no prueba OAuth, permisos ni respuestas del servidor. Usa las herramientas laid protegidas, no llamadas Atlassian directas.' };
  }
  async function sprintConfig(issue, config, tool, boardID) {
    if (config.board_id) {
      need(boardID === undefined || boardID === config.board_id, 'El tablero indicado difiere del configurado');
      return config;
    }
    const parentID = await owner(tool, false), parent = await ctx.session.get({ sessionID: parentID });
    need(parent.agent === 'laid-backlog' && sprintActions.some(a => config.allowed_actions?.includes(a)), 'Solo Backlog puede resolver una acción sprint ya autorizada');
    need(!writing, 'Hay una escritura en curso; no cambiar el mapeo');
    // El enum MCP no es el tipo REST: all incluye también tableros team-managed.
    const boards = await pages('atlassian_listJiraBoards', { projectKeyOrId: config.project, type: 'all' }, config, tool);
    const candidates = boards.filter(b => sprintBoard(b) && Number.isSafeInteger(b.id) && b.id > 0);
    need(candidates.length > 0, 'No hay tableros Scrum/team-managed visibles en el proyecto');
    const selectedID = config.board_id ?? boardID ?? (candidates.length === 1 ? candidates[0].id : null);
    if (selectedID === null) return { selection_required: 'board', question: '¿En qué tablero quieres trabajar?',
      choices: candidates.map((b, i) => ({ option: i + 1, id: b.id, label: b.name ?? `Tablero ${i + 1}`, type: b.type })) };
    need(candidates.some(b => b.id === selectedID), `Elige un tablero Scrum del proyecto: ${JSON.stringify(candidates.map(b => ({ id: b.id, name: b.name })))}`);
    need(boardID === undefined || boardID === selectedID, 'El tablero indicado difiere del configurado');
    const resolved = { ...config, board_id: selectedID };
    const root = fs.realpathSync(ctx.location.directory);
    const file = fs.realpathSync(path.join(root, '.laid/backlog-project.json'));
    need(file.startsWith(root + path.sep), 'Configuración fuera del proyecto');
    const document = JSON.parse(fs.readFileSync(file, 'utf8'));
    need(canonical(document.tracker) === canonical(config), 'Configuración cambiada durante el descubrimiento; releer');
    document.tracker = resolved;
    const temporary = `${file}.${randomUUID()}.tmp`;
    try {
      fs.writeFileSync(temporary, JSON.stringify(document, null, 2) + '\n', { flag: 'wx' });
      fs.renameSync(temporary, file);
    } finally { if (fs.existsSync(temporary)) fs.unlinkSync(temporary); }
    return resolved;
  }
  async function sprintCatalog(config, tool) {
    need(Number.isSafeInteger(config.board_id) && config.board_id > 0, 'Descubre primero el tablero con laid_jira_sprints');
    const boards = await pages('atlassian_listJiraBoards', { projectKeyOrId: config.project, type: 'all' }, config, tool);
    need(boards.some(b => b.id === config.board_id && sprintBoard(b)), 'Tablero fuera del proyecto o no visible');
    const values = await pages('atlassian_listJiraBoardSprints', { boardId: config.board_id, state: 'all' }, config, tool);
    need(values.every(s => Number.isSafeInteger(s.id) && s.id > 0 && typeof s.name === 'string'
      && ['future', 'active', 'closed'].includes(s.state) && s.originBoardId === config.board_id)
      && new Set(values.map(s => s.id)).size === values.length, 'Catálogo de sprints ambiguo o ajeno');
    return values.map(s => ({ id: s.id, name: s.name, state: s.state, originBoardId: s.originBoardId,
      goal: s.goal ?? null, startDate: s.startDate ?? null, endDate: s.endDate ?? null, completeDate: s.completeDate ?? null })).sort((a, b) => a.id - b.id);
  }
  async function listSprints(tool, boardID) {
    await owner(tool, false);
    const config = tracker();
    need(sprintActions.some(a => config.allowed_actions?.includes(a)), 'Acciones sprint no autorizadas en el proyecto');
    const resolved = await sprintConfig(null, config, tool, boardID);
    if (resolved.selection_required) return resolved;
    const values = await sprintCatalog(resolved, tool);
    return { project: config.project, board_id: resolved.board_id, values,
      choices: values.map((s, i) => ({ option: i + 1, id: s.id, label: `${s.name} (${s.state})` })),
      note: 'Elige por nombre/posición. Iniciar: future; terminar: active. Closed no se reabre. Los IDs son internos.' };
  }
  async function readSprint(sprintID, config, tool) {
    need(Number.isSafeInteger(sprintID) && sprintID > 0, 'ID de sprint inválido');
    const catalog = await sprintCatalog(config, tool), sprint = catalog.find(s => s.id === sprintID);
    need(sprint, 'Sprint no visible o fuera del tablero autorizado');
    const boardConfig = payload(await call('atlassian_getJiraBoardConfig', { cloudId: config.cloud_id, boardId: config.board_id }, tool));
    const columns = boardConfig.columnConfig?.columns;
    need(boardConfig.id === config.board_id && Array.isArray(columns) && columns.length > 0
      && columns.every(c => Array.isArray(c.statuses)), 'Columnas del tablero no verificables');
    const doneIDs = columns.at(-1).statuses.map(s => s.id).sort();
    need(doneIDs.length > 0 && doneIDs.every(id => typeof id === 'string'), 'Falta columna final verificable del tablero');
    // Inventario mínimo sin filtro project para detectar un sprint compartido antes de leer sus tareas.
    const keys = [], tokens = new Set(); let nextPageToken;
    for (;;) {
      const result = payload(await call('atlassian_searchJiraIssuesUsingJql', {
        cloudId: config.cloud_id, jql: `sprint = ${sprintID}`, fields: ['project'], maxResults: 100, view: 'full',
        ...(nextPageToken ? { nextPageToken } : {}),
      }, tool));
      need(Array.isArray(result.issues), 'Inventario de sprint incompleto');
      for (const item of result.issues) {
        need(new RegExp(`^${config.project}-[0-9]+$`).test(item.key)
          && (!item.fields?.project?.key || item.fields.project.key === config.project), 'Sprint contiene elementos de otro proyecto; no operar');
        need(!keys.includes(item.key), 'Inventario de sprint duplicado'); keys.push(item.key);
      }
      need(keys.length <= 1000, 'Sprint demasiado grande para una verificación completa');
      if (!result.nextPageToken) {
        need(result.isLast === true || (Number.isInteger(result.total) && keys.length === result.total), 'Inventario de sprint truncado o sin final verificable');
        break;
      }
      need(result.issues.length > 0 && !tokens.has(result.nextPageToken), 'Paginación de sprint incompleta');
      tokens.add(result.nextPageToken); nextPageToken = result.nextPageToken;
    }
    const issues = [];
    for (const key of keys.sort()) {
      const current = await read(key, config, tool), status = current.fields.status;
      need(typeof status?.id === 'string', 'Falta estado real de una tarea del sprint');
      issues.push({ key, summary: current.fields.summary, status: { id: status.id }, updated: current.fields.updated,
        done: doneIDs.includes(status.id), assigned_to_open_sprint: current.fields._laid_sprint_assigned });
    }
    const fields = { sprint, issues, done_status_ids: doneIDs, active_sprints: catalog.filter(s => s.state === 'active') };
    return { kind: 'sprint', sprint_id: sprintID, project: config.project, cloud_id: config.cloud_id, board_id: config.board_id,
      fields, sha256: hash(fields), read_at: new Date().toISOString(),
      url: `${config.site_url}/jira/software/projects/${config.project}/boards/${config.board_id}`,
      source: `opencode-session:${tool.sessionID}#${tool.messageID}/${tool.id}` };
  }
  async function observeSprint(sprintID, tool) {
    const sessionID = await owner(tool, false), config = tracker();
    need(['sprint_start', 'sprint_close'].some(a => config.allowed_actions?.includes(a)), 'Gestión de sprints no autorizada');
    return remember(await readSprint(sprintID, config, tool), sessionID);
  }
  async function sprintMatch(issue, condition, config, tool) {
    need(new RegExp(`^${config.project}-[0-9]+$`).test(issue), 'Elemento fuera del proyecto');
    const result = payload(await call('atlassian_searchJiraIssuesUsingJql', {
      cloudId: config.cloud_id, jql: `project = "${config.project}" AND key = "${issue}" AND (${condition})`,
      fields: ['project'], maxResults: 2, view: 'full',
    }, tool));
    need(Array.isArray(result.issues) && result.issues.length <= 1 && !result.nextPageToken && result.isLast !== false
      && (result.total === undefined || result.total <= 1)
      && result.issues.every(i => i.key === issue && (!i.fields?.project?.key || i.fields.project.key === config.project)),
    'Pertenencia de sprint no verificable');
    return result.issues.length === 1;
  }
  async function read(issue, config, tool, extraFields = []) {
    need(new RegExp(`^${config.project}-[0-9]+$`).test(issue), 'Elemento fuera del proyecto');
    const fields = [...new Set(['project', 'updated', 'summary', 'description', 'status', ...(config.allowed_fields ?? []), ...extraFields])].sort();
    const sprintField = config.sprint_field && fields.includes(config.sprint_field) ? config.sprint_field : null;
    const raw = await call('atlassian_getJiraIssue', { cloudId: config.cloud_id, issueIdOrKey: issue, fields, view: 'full',
      ...(sprintField ? { expand: 'schema' } : {}) }, tool);
    const result = payload(raw);
    if (sprintField) need(result.schema?.[sprintField]?.custom === 'com.pyxis.greenhopper.jira:gh-sprint', 'El campo configurado no es Sprint según el esquema real');
    need(result.key && result.fields?.project?.key, 'Lectura incompleta: faltan key o fields.project.key; revisar formato y vista de la respuesta MCP');
    need(result.key === issue && result.fields?.project?.key === config.project, 'Destino remoto no verificable');
    need(typeof result.fields.updated === 'string' && Number.isFinite(Date.parse(result.fields.updated)), 'Falta updated real');
    // Jira omite parent cuando no hay padre (por ejemplo, épicas); no es una lectura truncada.
    if (fields.includes('parent') && !Object.hasOwn(result.fields, 'parent')) result.fields.parent = null;
    need(fields.every(k => Object.hasOwn(result.fields, k)), 'Lectura incompleta; no usar un resumen');
    const state = Object.fromEntries(fields.map(k => [k, result.fields[k]]));
    if (config.board_id && sprintActions.some(a => config.allowed_actions?.includes(a)))
      state._laid_sprint_assigned = await sprintMatch(issue, '(sprint in openSprints() OR sprint in futureSprints())', config, tool);
    return { issue, cloud_id: config.cloud_id, project: config.project,
      url: config.site_url ? `${config.site_url}/browse/${issue}` : null, fields: state, sha256: hash(state),
      read_at: new Date().toISOString(), source: `opencode-session:${tool.sessionID}#${tool.messageID}/${tool.id}` };
  }
  async function observe(issue, tool) {
    const sessionID = await owner(tool, false);
    const state = await read(issue, tracker(), tool);
    return remember(state, sessionID);
  }
  const commentText = value => value.replace(/\r\n/g, '\n').replace(/\n+$/, '');
  async function readComments(issue, config, tool) {
    const state = await read(issue, config, tool);
